<?php
namespace App\Policies; use App\Models\{DueDiligenceItem,User}; use App\Policies\Concerns\CompanyOwnedPolicy;
class DueDiligenceItemPolicy { use CompanyOwnedPolicy; public function viewAny(User $u):bool{return $this->canForResource($u,'view_any_due_diligence_item');} public function view(User $u,DueDiligenceItem $r):bool{return $this->canForRecord($u,'view_due_diligence_item',$r);} public function create(User $u):bool{return $this->canForResource($u,'create_due_diligence_item');} public function update(User $u,DueDiligenceItem $r):bool{return $this->canForRecord($u,'update_due_diligence_item',$r);} public function delete(User $u,DueDiligenceItem $r):bool{return $this->canForRecord($u,'delete_due_diligence_item',$r);} public function waive(User $u,DueDiligenceItem $r):bool{return $this->canForRecord($u,'waive_due_diligence_item',$r);} }
